-- Capability Proof only. Immutable copies of inactive, attempt-free revisions.
-- Reviewed prompts/options/feedback: docs/qualification-content/20261013_evidence_exception_reviewed_inventory.json
BEGIN;
SELECT pg_advisory_xact_lock(hashtextextended('ri_20261013_exception_bank_staging',0));
CREATE TEMP TABLE _ri_semantic_versions ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"assessment_key":"handover_verification_mastery_v1","from_version":13,"to_version":14},{"assessment_key":"how_the_system_resolves_uncertainty_mastery_v1","from_version":18,"to_version":19},{"assessment_key":"how_to_interpret_prompts_mastery_v1","from_version":19,"to_version":20},{"assessment_key":"intro_session_structure_mastery_v1","from_version":16,"to_version":17},{"assessment_key":"logging_system_mastery_v1","from_version":17,"to_version":18},{"assessment_key":"operating_system_transfer_v2","from_version":5,"to_version":6},{"assessment_key":"what_not_to_do_mastery_v1","from_version":14,"to_version":15}]'::jsonb) AS v(assessment_key text,from_version integer,to_version integer);
CREATE TEMP TABLE _ri_semantic_edits ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"assessment_key":"handover_verification_mastery_v1","item_key":"handover_verification_q14_base","prompt":"In a Handover verification, the Specialist supplies a mathematical step before the student independently chooses it. How should the affected first-step claim be recorded?","options":[{"key":"a","label":"Treat the student''s completed answer after assistance as proof of independent first-step control."},{"key":"b","label":"Record the mathematical step supplied by the Specialist as an intervention, not independent first-step control."},{"key":"c","label":"Preserve what the student actually did afterward and keep the assistance separate from independent first-step control."},{"key":"d","label":"Hide the Specialist''s supplied step because the later student response was correct."},{"key":"e","label":"Mark independent first-step control as breakdown solely because the Specialist intervened."}],"explanation":"Record the supplied mathematical step as an intervention and retain the student response separately. Assisted execution cannot establish independent first-step control; RI-OS directs any subsequent check.","option_feedback":{"a":"Finishing after receiving the step does not prove the affected move was independent.","d":"Recorded assistance remains part of the evidence regardless of the final answer.","e":"Specialist intervention is not itself proof of student inability."}},{"assessment_key":"how_the_system_resolves_uncertainty_mastery_v1","item_key":"how_the_system_resolves_uncertainty_f13_base","prompt":"Why may RI-OS open a comparable Handover opportunity when the inherited record does not establish a required claim?","options":[{"key":"a","label":"Open another comparable opportunity only to resolve the specific missing Handover evidence, then stop once that question is resolved."},{"key":"b","label":"To answer the specific unresolved evidence question under a comparable condition."},{"key":"c","label":"To give the student another chance to produce a stronger result."},{"key":"d","label":"To keep practising until every Handover dimension eventually looks strong, regardless of the unresolved evidence question."},{"key":"e","label":"To satisfy a fixed rep quota regardless of evidence."}],"explanation":"Continuation exists to resolve uncertainty, not to chase improvement.","option_feedback":{"c":"A weak student response under valid timing is evidence, not permission for another attempt.","d":"Continuation exists to resolve a specific missing continuity dimension, not to practise until every dimension looks positive.","e":"That choice does not preserve the exact operating boundary the opportunity is meant to test."}},{"assessment_key":"how_the_system_resolves_uncertainty_mastery_v1","item_key":"uncertainty_extra_25","prompt":"Why may RI-OS request a comparable opportunity for an unresolved inherited-state claim?","options":[{"key":"a","label":"To keep repeating continuity work until every field appears positive, even after the specific question is answered."},{"key":"b","label":"To answer that specific unresolved evidence question."},{"key":"c","label":"Open another comparable opportunity only to resolve the specific missing Handover evidence, then stop once that question is resolved."},{"key":"d","label":"To give the student another chance to look stronger."},{"key":"e","label":"To fill a fixed rep quota."}],"explanation":"Continuation is bounded by unresolved evidence, not desired performance.","option_feedback":{"a":"Repeating until all fields are positive turns uncertainty resolution into outcome-chasing.","d":"The next opportunity exists to answer the missing dimension, not to give the student a stronger-looking result.","e":"There is no fixed rep quota once the specific continuity question is resolved."}},{"assessment_key":"how_to_interpret_prompts_mastery_v1","item_key":"interpret_prompts_extra_28","prompt":"Which proposed actions preserve an evidence field that has no qualifying direct observation?","options":[{"key":"a","label":"Mark the requested unobserved dimension supported because a later correct answer or related dimension looked strong."},{"key":"b","label":"Leave the requested unobserved dimension unresolved until there is qualifying direct evidence; its absence is not a student failure."},{"key":"c","label":"Preserve other reliable observations separately, and let RI-OS request a clean equivalent opportunity if the requested unobserved dimension is needed."},{"key":"d","label":"Represent the requested unobserved dimension as lacking qualifying evidence rather than filling it with an assumed response."},{"key":"e","label":"Mark the requested unobserved dimension as a capability breakdown because qualifying evidence is missing."}],"explanation":"No qualifying direct evidence establishes the requested unobserved dimension. Preserve the evidence status without inventing a simulated missing-observation incident. The Specialist must neither score the student weak nor strong from absence; RI-OS determines whether a fresh comparable check is needed.","option_feedback":{"a":"A strong later answer cannot substitute for a direct observation of the exact claim.","e":"Missing evidence is not a student breakdown."}},{"assessment_key":"intro_session_structure_mastery_v1","item_key":"v2r8_intro_session_structure_20","prompt":"During a diagnostic independence check, a student sees a worked example naming the method before selecting it. Earlier evidence is mixed and RI-OS cannot resolve the starting state yet. What must happen?","options":[{"key":"a","label":"Treat the unresolved diagnostic independence claim as supported because the student eventually gave the right answer."},{"key":"b","label":"Treat the visible worked example as proof the student lacks the relevant capability."},{"key":"c","label":"Record the worked example cue and classify the affected diagnostic independence claim as confounded, not clean independence."},{"key":"d","label":"Ignore the method cue because the student subsequently wrote the steps themselves."},{"key":"e","label":"Preserve unrelated clean observations, then obtain independent evidence for the unresolved diagnostic independence claim if RI-OS still requires it."}],"explanation":"A worked example visibly supplied mathematics relevant to the unresolved diagnostic independence claim. That rare cue confounds only the affected independent claim. Preserve separate clean behaviour; remove the reference and recheck when RI-OS requires it. The prescribed method remains unchanged.","option_feedback":{"a":"The worked reference supplied information needed for the independence question.","b":"Reference exposure limits interpretation; it is not direct evidence of weakness.","d":"Later student-authored steps can be influenced by the visible worked method."}},{"assessment_key":"logging_system_mastery_v1","item_key":"v2r8_logging_system_15","prompt":"A completed Training set includes an independent-execution opportunity in which a worked example was visible and consulted. How should the Specialist preserve affected and unaffected evidence?","options":[{"key":"a","label":"Treat the affected independent-execution opportunity as supported because the student eventually gave the right answer."},{"key":"b","label":"Treat the visible worked example as proof the student lacks the relevant capability."},{"key":"c","label":"Record the worked-example cue, exclude the affected independence claim from clean proof, and preserve separately observed clean dimensions."},{"key":"d","label":"Ignore the method cue because the student subsequently wrote the steps themselves."},{"key":"e","label":"Change the originally prescribed method to match the displayed reference and call the result independent."}],"explanation":"A worked example visibly supplied mathematics relevant to the affected independent-execution opportunity. That rare cue confounds only the affected independent claim. Preserve separate clean behaviour; remove the reference and recheck when RI-OS requires it. The prescribed method remains unchanged.","option_feedback":{"a":"The worked reference supplied information needed for the independence question.","b":"Reference exposure limits interpretation; it is not direct evidence of weakness.","d":"Later student-authored steps can be influenced by the visible worked method.","e":"The prescribed mathematical method remains unchanged; changing it cannot cure the cue."}},{"assessment_key":"operating_system_transfer_v2","item_key":"ost_logging_04","prompt":"A rep begins cleanly, but the student later consults a visible worked solution while the Specialist also provides a mathematical prompt. Which statements preserve the separate evidence effects?","options":[{"key":"a","label":"Record the consulted worked example and the Specialist''s mathematical prompt separately; neither supplies clean independence for the affected steps."},{"key":"b","label":"Preserve unrelated clean observations, then obtain independent evidence for the cue-affected independence claim if RI-OS still requires it."},{"key":"c","label":"Treat the cue-affected independence claim as supported because the student eventually gave the right answer."},{"key":"d","label":"Keep the taught task and method unchanged while excluding the cue-affected independence claim from clean capability proof."},{"key":"e","label":"Treat the visible worked example as proof the student lacks the relevant capability."}],"explanation":"Preserve the clean opening. Record both the consulted worked example and the Specialist''s mathematical intervention, including their effects on later independence. Neither changes the prescribed task or proves weakness. RI-OS determines whether fresh independent evidence is needed.","option_feedback":{"c":"The worked reference supplied information needed for the independence question.","e":"Reference exposure limits interpretation; it is not direct evidence of weakness."}},{"assessment_key":"what_not_to_do_mastery_v1","item_key":"what_not_to_do_extra_05","prompt":"An inherited record does not establish method recognition directly. How should the Specialist preserve that claim?","options":[{"key":"a","label":"Mark method recognition supported because a later correct answer or related dimension looked strong."},{"key":"b","label":"Mark method recognition as a capability breakdown because qualifying evidence is missing."},{"key":"c","label":"Reconstruct method recognition from a likely explanation and record it as a directly observed response."},{"key":"d","label":"Choose a favourable state for method recognition to avoid another evidence check."},{"key":"e","label":"Leave method recognition unresolved until there is qualifying direct evidence; its absence is not a student failure."}],"explanation":"No qualifying direct evidence establishes method recognition. Preserve the evidence status without inventing a simulated missing-observation incident. The Specialist must neither score the student weak nor strong from absence; RI-OS determines whether a fresh comparable check is needed.","option_feedback":{"a":"A strong later answer cannot substitute for a direct observation of the exact claim.","b":"Missing evidence is not a student breakdown.","c":"An inference or recollection cannot be substituted for the original observation.","d":"A preferred decision cannot close an unresolved evidence question."}},{"assessment_key":"what_not_to_do_mastery_v1","item_key":"what_not_to_do_extra_12","prompt":"The student has five seconds left and is still working correctly. The Specialist shouts ''finish now.'' What evidence is affected?","options":[{"key":"a","label":"The student''s own pace control is contaminated by external pacing."},{"key":"b","label":"The added pacing intervention contaminates evidence of self-regulated pace, even though the original timer remained active."},{"key":"c","label":"None, because the timer already created urgency."},{"key":"d","label":"Only emotional comfort is affected."},{"key":"e","label":"The rep becomes stronger because the student experienced more pressure."}],"explanation":"Specialist-created urgency is not part of the intended timed condition.","option_feedback":{"c":"The existing timer creates urgency; the Specialist''s “finish now” cue adds a second external pacing input.","d":"The cue directly changes pace regulation, not merely comfort.","e":"More pressure from the Specialist weakens evidence of the student''s own response under the authorized timer."}}]'::jsonb) AS p(assessment_key text,item_key text,prompt text,options jsonb,explanation text,option_feedback jsonb);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _ri_semantic_versions v LEFT JOIN private.specialist_capability_assessment_configs c ON c.assessment_key=v.assessment_key AND c.bank_version=v.from_version WHERE c.assessment_key IS NULL OR c.active OR c.review_mode) THEN RAISE EXCEPTION 'Expected inactive source missing'; END IF;
 IF EXISTS(SELECT 1 FROM _ri_semantic_versions v JOIN private.specialist_capability_assessment_configs c ON c.assessment_key=v.assessment_key AND c.bank_version=v.to_version) THEN RAISE EXCEPTION 'Successor already exists; refuse overwrite'; END IF;
 IF EXISTS(SELECT 1 FROM _ri_semantic_versions v JOIN public.specialist_capability_assessment_attempts a ON a.assessment_key=v.assessment_key AND a.bank_version=v.from_version) THEN RAISE EXCEPTION 'Source has attempts'; END IF;
 IF EXISTS(SELECT 1 FROM _ri_semantic_edits e JOIN _ri_semantic_versions v USING(assessment_key) LEFT JOIN private.specialist_capability_assessment_items i ON i.assessment_key=e.assessment_key AND i.bank_version=v.from_version AND i.item_key=e.item_key WHERE i.item_key IS NULL) THEN RAISE EXCEPTION 'Correction source missing'; END IF;
END $$;
INSERT INTO private.specialist_capability_assessment_configs(assessment_key,bank_version,title,assessment_deep_dive_key,evidence_kind,pass_threshold_percent,form_size,max_attempts,retry_cooldown_hours,competency_blueprint,active,created_at,retired_at,review_mode)
SELECT c.assessment_key,v.to_version,c.title,c.assessment_deep_dive_key,c.evidence_kind,c.pass_threshold_percent,c.form_size,c.max_attempts,c.retry_cooldown_hours,c.competency_blueprint,false,NOW(),NULL,false FROM private.specialist_capability_assessment_configs c JOIN _ri_semantic_versions v ON v.assessment_key=c.assessment_key AND v.from_version=c.bank_version;
INSERT INTO private.specialist_capability_assessment_items(assessment_key,bank_version,item_key,competency_key,deep_dive_key,prompt,question_kind,options,correct_option_keys,critical_fail_option_keys,critical_boundary_keys,explanation,active,created_at,option_feedback)
SELECT i.assessment_key,v.to_version,i.item_key,i.competency_key,i.deep_dive_key,COALESCE(e.prompt,i.prompt),i.question_kind,COALESCE(e.options,i.options),i.correct_option_keys,i.critical_fail_option_keys,i.critical_boundary_keys,COALESCE(e.explanation,i.explanation),i.active,NOW(),COALESCE(e.option_feedback,i.option_feedback) FROM private.specialist_capability_assessment_items i JOIN _ri_semantic_versions v ON v.assessment_key=i.assessment_key AND v.from_version=i.bank_version LEFT JOIN _ri_semantic_edits e ON e.assessment_key=i.assessment_key AND e.item_key=i.item_key;
-- Separate canonical metadata repair; no answer-key or historical evidence change.
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM private.specialist_capability_assessment_items WHERE assessment_key='operating_system_transfer_v2' AND bank_version=5 AND item_key='ost2_training_purpose_01' AND critical_boundary_keys='["training_purpose.no_diagnosis_as_training"]'::jsonb AND critical_fail_option_keys='["b"]'::jsonb AND correct_option_keys='["a","c"]'::jsonb) THEN RAISE EXCEPTION 'Transfer critical metadata predecessor drift'; END IF;
END $$;
UPDATE private.specialist_capability_assessment_items SET critical_boundary_keys='["training_purpose.no_diagnosis_as_training","training_purpose.no_stop_at_clarity"]'::jsonb, critical_fail_option_keys='["b","e"]'::jsonb WHERE assessment_key='operating_system_transfer_v2' AND bank_version=6 AND item_key='ost2_training_purpose_01';
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _ri_semantic_versions v WHERE (SELECT count(*) FROM private.specialist_capability_assessment_items i WHERE i.assessment_key=v.assessment_key AND i.bank_version=v.from_version)<>(SELECT count(*) FROM private.specialist_capability_assessment_items i WHERE i.assessment_key=v.assessment_key AND i.bank_version=v.to_version)) THEN RAISE EXCEPTION 'Pool count changed'; END IF;
 IF EXISTS(SELECT 1 FROM _ri_semantic_edits e JOIN _ri_semantic_versions v USING(assessment_key) JOIN private.specialist_capability_assessment_items i ON i.assessment_key=e.assessment_key AND i.bank_version=v.to_version AND i.item_key=e.item_key WHERE (i.prompt,i.options,i.explanation,i.option_feedback) IS DISTINCT FROM (e.prompt,e.options,e.explanation,e.option_feedback)) THEN RAISE EXCEPTION 'Semantic replacement mismatch'; END IF;
END $$;
COMMIT;
